    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __size(name, prop, v) {
      var s = $(name).style;
      if (prop === 'opacity') s.opacity = v / 100;
      else if (prop === 'rotate') s.transform = 'rotate(' + v + 'deg)';
      else s[prop] = v + 'px';
    }

    var n;

    document.getElementById("btn").addEventListener('click', function () {
      n = (typeof n === 'number' ? n : 0) + 1;
      document.getElementById("fond").style.background = 'hsl(' + Math.floor(Math.random() * 360) + ', 80%, 60%)';
