    body { margin: 0; padding: 24px; font-family: system-ui, "Apple SD Gothic Neo", "Noto Sans KR", sans-serif; line-height: 1.5; background: #e0f2fe; color: #1f2937; text-align: center; }
    button { font: inherit; font-weight: 700; padding: 10px 18px; margin: 4px; border: 0; border-radius: 10px; background: #ffc93c; color: #1c1405; cursor: pointer; }
  </style>
</head>
<body>
  <h2 id="sc">점수: 0</h2>
  <p id="tm">남은 시간: 10</p>
  <button id="go">눌러!</button>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __show(name, mode) {
      var el = $(name);
      if (mode === 'toggle') mode = el.style.display === 'none' ? 'show' : 'hide';
      el.style.display = mode === 'hide' ? 'none' : '';
    }
    var __timers = [];

    var score, time;

    document.getElementById("go").addEventListener('click', function () {
      score = (typeof score === 'number' ? score : 0) + 1;
      document.getElementById("sc").textContent = '점수: ' + String(score);
    });
    __timers.push(setInterval(function () {
      time = (typeof time === 'number' ? time : 0) + -1;
      document.getElementById("tm").textContent = '남은 시간: ' + String(time);
      if (time == 0) {
        __timers.forEach(clearInterval);
        __show("go", "hide");
        alert('끝! 점수는 ' + String(score));
      }
    }, 1000));

    score = 0;
    time = 10;
  </script>
</body>
</html>
