    input { font: inherit; padding: 9px 12px; margin: 4px; border: 1px solid #9ca3af; border-radius: 9px; }
    canvas { max-width: 100%; background: #ffffff; border: 1px solid #d1d5db; border-radius: 8px; touch-action: manipulation; }
    .box { display: flex; flex-direction: column; gap: 8px; padding: 12px; margin: 8px 0; border-radius: 12px; align-items: center; }
    .box.row { flex-direction: row; flex-wrap: wrap; align-items: center; justify-content: center; }
  </style>
</head>
<body>
  <h2 id="title1">막대그래프</h2>
  <canvas id="chart" width="400" height="200"></canvas>
  <div id="row1" class="box row">
    <input id="hBox" type="number" placeholder="높이">
    <button id="addBtn">추가</button>
  </div>
  <p id="countText">0 / 10개</p>
  <script>
    function $(name) {
      var el = document.getElementById(name);
      if (!el) throw new Error('"' + name + '" 요소가 없어요');
      return el;
    }
    function __pen(name) { return $(name).getContext('2d'); }
    function __rect(name, x, y, w, h, color) { var g = __pen(name); g.fillStyle = color; g.fillRect(x, y, w, h); }

    var n, h;

    document.getElementById("addBtn").addEventListener('click', function () {
      if (n >= 10) {
        alert('막대는 10개까지만 돼요');
      } else {
        h = Math.min(Math.max((parseFloat(document.getElementById("hBox").value) || 0), 0), 200);
        __rect("chart", 10 + n * 40, 200 - h, 30, h, "#3b82f6");
        n = (typeof n === 'number' ? n : 0) + 1;
        document.getElementById("countText").textContent = String(n) + ' / 10개';
      }
    });

    n = 0;
  </script>
</body>
</html>
